<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/conversation_support.php';
require_once __DIR__ . '/report_activity.php';
require_once __DIR__ . '/workflow_support.php';

require_once __DIR__ . '/evidence_support.php';
if (!isset($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$id = (int) ($_GET['id'] ?? 0);
if (in_array($_SESSION['role'] ?? '', ['admin','staff'], true)) { header('Location: admin/edit_complaint.php?id=' . $id . '#conversation'); exit; }
if (($_SESSION['role'] ?? '') !== 'resident') { http_response_code(403); exit; }
$query = $pdo->prepare('SELECT * FROM complaints WHERE id=? AND user_id=?'); $query->execute([$id, $_SESSION['user_id']]); $complaint = $query->fetch(PDO::FETCH_ASSOC);
if (!$complaint) { http_response_code(404); exit('Complaint not found.'); }
$query = $pdo->prepare('SELECT * FROM complaint_evidence WHERE complaint_id=? ORDER BY id'); $query->execute([$id]); $evidence = $query->fetchAll(PDO::FETCH_ASSOC);
?>
